bgaOccurrence.sourceBlockText:
ServerRobot: {
  name: 'Server Robot',
  desc: [
    'Move the <ROBOT> up to 3 times.',
    'If the <ROBOT> is in a <COMPUTER> Room, use the Room (even with a <MALFUNCTION>).',
  ],
  color: 'other',
},

SecuringRobot: {
  name: 'Securing Robot',
  desc: [
    'Move the <ROBOT> up to 3 times.',
    'Open or Close 1 Door accessible to the <ROBOT>.',
    'Place 2 <SECURE> in a Room with the <ROBOT>.',
  ],
  color: 'other',
},

ExplorationRobot: {
  name: 'Exploration Robot',
  desc: [
    'Move the <ROBOT> up to 2 times.',
    'Move the <ROBOT> through an Unexplored Corridor and resolve an Exploration Sequence. Do not resolve the Entrance effect.',
  ],
  color: 'yellow',
},

TechnicalRobot: {
  name: 'Technical Robot',
  desc: ['Move the <ROBOT> up to 2 times.', 'Discard a <MALFUNCTION> or a <FIRE> from the Room with the <ROBOT>.'],
  color: 'yellow',
},

MedicalRobot: {
  name: 'Medical Robot',
  desc: [
    'Move the <ROBOT> up to 2 times.',
    'A <CHARACTER> of your choice in a Room with the <ROBOT> discards 1 Serious Wound or restores 2<HP>.',
  ],
  color: 'green',
},

MilitaryRobot: {
  name: 'Military Robot',
  desc: [
    'Move the <ROBOT> once.',
    'Choose a Corridor adjacent to the <ROBOT> and roll a Burst die. Deal Hits equal to the result in that Corridor.\n<DICE-BURST>: Place a <MALFUNCTION> on the <ROBOT>',
  ],
  color: 'red',
},
